impl BodyError for crate::contracts::ApplyLabChangeError {
    fn body(&self) -> types::ApiError {
        match self {
            Self::Unauthenticated(body) => {
                let mut body = body.clone();
                body.code = types::ErrorCode::Unauthenticated;
                body
            }
            Self::Forbidden(body) => {
                let mut body = body.clone();
                body.code = types::ErrorCode::Forbidden;
                body
            }
            Self::StepUpRequired(body) => {
                let mut body = body.clone();
                body.code = types::ErrorCode::Forbidden;
                body
            }
            Self::Invalid(body) => {
                let mut body = body.clone();
                body.code = types::ErrorCode::Invalid;
                body
            }
            Self::NotFound(body) => {
                let mut body = body.clone();
                body.code = types::ErrorCode::NotFound;
                body
            }
            Self::Conflict(body) => {
                let mut body = body.clone();
                body.code = types::ErrorCode::Conflict;
                body
            }
            Self::TenantMismatch(body) => {
                let mut body = body.clone();
                body.code = types::ErrorCode::Forbidden;
                body
            }
        }
    }

    fn from_body(body: types::ApiError) -> Option<Self> {
        match body.code {
            types::ErrorCode::Unauthenticated => Some(Self::Unauthenticated(body)),
            types::ErrorCode::Invalid => Some(Self::Invalid(body)),
            types::ErrorCode::NotFound => Some(Self::NotFound(body)),
            types::ErrorCode::Conflict => Some(Self::Conflict(body)),
            _ => None,
        }
    }
}

