/// What the route of contract `aggregate-run` needs from the deployment beyond its handler.
pub trait AggregateRunHooks: Send + Sync + 'static + QuotaCounter {
    /// The payload of error `throttled` of contract `aggregate-run` when quota `q-aggregate-run` refuses a call, `retry_after` before the window ends.
    fn q_aggregate_run_exceeded(&self, retry_after: std::time::Duration) -> types::ApiError;
}

/// Answers one call of contract `aggregate-run`.
async fn answer_aggregate_run<S: AggregateRunHandler, H: AggregateRunHooks>(
    handler: &S,
    hooks: &H,
    caller: strata_runtime::Caller,
    request: crate::contracts::AggregateRunRequest,
) -> Result<
    crate::contracts::AggregateRunResponse,
    strata_runtime::Failure<crate::contracts::AggregateRunError>,
> {
    let principal = principal(&caller);
    match hooks
        .count(&crate::quotas::Q_AGGREGATE_RUN, &principal)
        .await
        .map_err(|why| refusal(strata_runtime::FailureCode::Unavailable, why))?
    {
        crate::quotas::QuotaOutcome::Allowed(_) => {}
        crate::quotas::QuotaOutcome::Exceeded { retry_after, .. } => {
            return Err(strata_runtime::Failure::Contract {
                error: crate::contracts::AggregateRunError::Throttled(
                    hooks.q_aggregate_run_exceeded(retry_after),
                ),
            });
        }
    }
    handler
        .handle(request)
        .await
        .map_err(|error| strata_runtime::Failure::Contract { error })
}

/// Adds the route of contract `aggregate-run` to `routes`, answered by `handler` after the checks the specification states for it.
pub fn serve_aggregate_run<A, S, H>(
    routes: strata_runtime::Routes<A>,
    handler: std::sync::Arc<S>,
    hooks: std::sync::Arc<H>,
) -> strata_runtime::Routes<A>
where
    A: strata_runtime::Authorizer,
    S: AggregateRunHandler,
    H: AggregateRunHooks,
{
    routes.serve_checked::<AggregateRun, _, _>(
        move |caller: strata_runtime::Caller, request: crate::contracts::AggregateRunRequest| {
            let (handler, hooks) = (handler.clone(), hooks.clone());
            async move { answer_aggregate_run(&*handler, &*hooks, caller, request).await }
        },
    )
}

