/// What the route of contract `list-sign-in-providers` needs from the deployment beyond its handler.
pub trait ListSignInProvidersHooks: Send + Sync + 'static + QuotaCounter + QuotaWait {}

/// The route of contract `list-sign-in-providers` needs no hook of its own.
impl<T: Send + Sync + 'static + QuotaCounter + QuotaWait> ListSignInProvidersHooks for T {}

/// Answers one call of contract `list-sign-in-providers`.
async fn answer_list_sign_in_providers<
    S: ListSignInProvidersHandler,
    H: ListSignInProvidersHooks,
>(
    handler: &S,
    hooks: &H,
    caller: strata_runtime::Caller,
    request: crate::contracts::ListSignInProvidersRequest,
) -> Result<
    crate::contracts::ListSignInProvidersResponse,
    strata_runtime::Failure<crate::contracts::ListSignInProvidersError>,
> {
    let principal = principal(&caller);
    match hooks
        .count(&crate::quotas::Q_LIST_SIGN_IN_PROVIDERS, &principal)
        .await
        .map_err(|why| refusal(strata_runtime::FailureCode::Unavailable, why))?
    {
        crate::quotas::QuotaOutcome::Allowed(_) => {}
        crate::quotas::QuotaOutcome::Exceeded { retry_after, .. } => {
            hooks
                .wait(&crate::quotas::Q_LIST_SIGN_IN_PROVIDERS, retry_after)
                .await;
        }
    }
    handler
        .handle(request)
        .await
        .map_err(|error| strata_runtime::Failure::Contract { error })
}

/// Adds the route of contract `list-sign-in-providers` to `routes`, answered by `handler` after the checks the specification states for it.
