/// What the route of contract `complete-recovery` needs from the deployment beyond its handler.
pub trait CompleteRecoveryHooks: Send + Sync + 'static + QuotaCounter {
    /// The payload of error `throttled` of contract `complete-recovery` when quota `q-complete-recovery` refuses a call, `retry_after` before the window ends.
    fn q_complete_recovery_exceeded(&self, retry_after: std::time::Duration) -> types::ApiError;
}

/// Answers one call of contract `complete-recovery`.
async fn answer_complete_recovery<S: CompleteRecoveryHandler, H: CompleteRecoveryHooks>(
    handler: &S,
    hooks: &H,
    caller: strata_runtime::Caller,
    request: crate::contracts::CompleteRecoveryRequest,
) -> Result<
    crate::contracts::CompleteRecoveryResponse,
    strata_runtime::Failure<crate::contracts::CompleteRecoveryError>,
> {
    let principal = principal(&caller);
    match hooks
        .count(&crate::quotas::Q_COMPLETE_RECOVERY, &principal)
        .await
        .map_err(|why| refusal(strata_runtime::FailureCode::Unavailable, why))?
    {
        crate::quotas::QuotaOutcome::Allowed(_) => {}
        crate::quotas::QuotaOutcome::Exceeded { retry_after, .. } => {
            return Err(strata_runtime::Failure::Contract {
                error: crate::contracts::CompleteRecoveryError::Throttled(
                    hooks.q_complete_recovery_exceeded(retry_after),
                ),
            });
        }
    }
    handler
        .handle(request)
        .await
        .map_err(|error| strata_runtime::Failure::Contract { error })
}

