/// What the route of contract `run-lab-projection` needs from the deployment beyond its handler.
pub trait RunLabProjectionHooks: Send + Sync + 'static + QuotaCounter {
    /// The payload of error `throttled` of contract `run-lab-projection` when quota `q-run-lab-projection` refuses a call, `retry_after` before the window ends.
    fn q_run_lab_projection_exceeded(&self, retry_after: std::time::Duration) -> types::ApiError;
}

/// Answers one call of contract `run-lab-projection`.
async fn answer_run_lab_projection<S: RunLabProjectionHandler, H: RunLabProjectionHooks>(
    handler: &S,
    hooks: &H,
    caller: strata_runtime::Caller,
    request: crate::contracts::RunLabProjectionRequest,
) -> Result<
    crate::contracts::RunLabProjectionResponse,
    strata_runtime::Failure<crate::contracts::RunLabProjectionError>,
> {
    let principal = principal(&caller);
    match hooks
        .count(&crate::quotas::Q_RUN_LAB_PROJECTION, &principal)
        .await
        .map_err(|why| refusal(strata_runtime::FailureCode::Unavailable, why))?
    {
        crate::quotas::QuotaOutcome::Allowed(_) => {}
        crate::quotas::QuotaOutcome::Exceeded { retry_after, .. } => {
            return Err(strata_runtime::Failure::Contract {
                error: crate::contracts::RunLabProjectionError::Throttled(
                    hooks.q_run_lab_projection_exceeded(retry_after),
                ),
            });
        }
    }
    handler
        .handle(request)
        .await
        .map_err(|error| strata_runtime::Failure::Contract { error })
}

