/// Adds the route of every contract component `identity-service` implements to `routes`, each answered by `service` after the checks the specification states for it.
pub fn identity_service_routes<A, S, H>(
    routes: strata_runtime::Routes<A>,
    service: std::sync::Arc<S>,
    hooks: std::sync::Arc<H>,
) -> strata_runtime::Routes<A>
where
    A: strata_runtime::Authorizer,
    S: crate::contracts::IdentityService + Send + Sync + 'static,
    H: IdentityServiceHooks,
{
    let routes = serve_list_sign_in_providers(routes, service.clone(), hooks.clone());
    let routes = serve_start_passkey_registration(routes, service.clone(), hooks.clone());
    let routes = serve_step_up_session(routes, service.clone(), hooks.clone());
    let routes = serve_list_factors(routes, service.clone(), hooks.clone());
    let routes = serve_start_totp_enrolment(routes, service.clone(), hooks.clone());
    let routes = serve_confirm_totp_enrolment(routes, service.clone(), hooks.clone());
    let routes = serve_remove_totp_factor(routes, service.clone(), hooks.clone());
    let routes = serve_regenerate_recovery_codes(routes, service.clone(), hooks.clone());
    let routes = serve_complete_recovery(routes, service.clone(), hooks.clone());
    let routes = serve_cancel_recovery(routes, service.clone(), hooks.clone());
    let routes = serve_revoke_other_sessions(routes, service.clone(), hooks.clone());
    let routes = serve_list_identity_clients(routes, service.clone(), hooks.clone());
    let routes = serve_introspect_token_over_http(routes, service.clone(), hooks.clone());
    let routes = serve_serve_jwks_document(routes, service.clone(), hooks.clone());
    serve_accept_site_invitation(routes, service, hooks)
}

