/// Adds the route of every contract component `gateway` implements to `routes`, each answered by `service` after the checks the specification states for it.
pub fn gateway_routes<A, S, H>(
    routes: strata_runtime::Routes<A>,
    service: std::sync::Arc<S>,
    hooks: std::sync::Arc<H>,
) -> strata_runtime::Routes<A>
where
    A: strata_runtime::Authorizer,
    S: crate::contracts::Gateway + Send + Sync + 'static,
    H: GatewayHooks,
{
    let routes = serve_subscribe_events(routes, service.clone(), hooks.clone());
    let routes = serve_sign_media_address(routes, service.clone(), hooks.clone());
    let routes = serve_deliver_file(routes, service.clone(), hooks.clone());
    let routes = serve_issue_request_token(routes, service.clone(), hooks.clone());
    let routes = serve_check_request_token(routes, service.clone(), hooks.clone());
    let routes = serve_set_session_cookie(routes, service.clone(), hooks.clone());
    let routes = serve_call_internal_service(routes, service.clone(), hooks.clone());
    let routes = serve_sign_in_at_site(routes, service.clone(), hooks.clone());
    let routes = serve_sign_out_of_site(routes, service.clone(), hooks.clone());
    let routes = serve_read_session_view(routes, service.clone(), hooks.clone());
    let routes = serve_preview_markdown(routes, service.clone(), hooks.clone());
    let routes = serve_assign_role(routes, service.clone(), hooks.clone());
    let routes = serve_revoke_role(routes, service.clone(), hooks.clone());
    let routes = serve_add_team_member(routes, service.clone(), hooks.clone());
    let routes = serve_remove_team_member(routes, service.clone(), hooks.clone());
    let routes = serve_invite_person(routes, service.clone(), hooks.clone());
    let routes = serve_redeem_invitation(routes, service.clone(), hooks.clone());
    let routes = serve_define_segment(routes, service.clone(), hooks.clone());
    let routes = serve_remove_segment(routes, service.clone(), hooks.clone());
    let routes = serve_list_segment_members(routes, service.clone(), hooks.clone());
    let routes = serve_test_segment_predicate(routes, service.clone(), hooks.clone());
    let routes = serve_setting_save_definition(routes, service.clone(), hooks.clone());
    let routes = serve_setting_resolve(routes, service.clone(), hooks.clone());
    let routes = serve_setting_resolve_all(routes, service.clone(), hooks.clone());
    let routes = serve_setting_definitions(routes, service.clone(), hooks.clone());
    let routes = serve_setting_set_tenant(routes, service.clone(), hooks.clone());
    let routes = serve_setting_set_team(routes, service.clone(), hooks.clone());
    let routes = serve_setting_set_person(routes, service.clone(), hooks.clone());
    let routes = serve_aggregate_run(routes, service.clone(), hooks.clone());
    let routes = serve_resolve_recipient_setting(routes, service.clone(), hooks.clone());
    let routes = serve_list_my_segments(routes, service.clone(), hooks.clone());
    let routes = serve_count_segment_members(routes, service.clone(), hooks.clone());
    let routes = serve_preview_segment_predicate(routes, service.clone(), hooks.clone());
    let routes = serve_read_diagnostics(routes, service.clone(), hooks.clone());
    let routes = serve_run_development_action(routes, service.clone(), hooks.clone());
    serve_withdraw_invitation(routes, service, hooks)
}

