    let routes = serve_list_automation_runs(routes, service.clone(), hooks.clone());
    let routes = serve_list_automation_steps(routes, service.clone(), hooks.clone());
    let routes = serve_list_automation_exceptions(routes, service.clone(), hooks.clone());
