pub trait SubjectRightsServiceHooks:
    ExportSubjectDataHooks
    + RestrictSubjectHooks
    + EraseSubjectHooks
    + PlaceLegalHoldHooks
    + ListErasureReceiptsHooks
    + FetchSubjectExportHooks
    + LiftSubjectRestrictionHooks
    + ReleaseLegalHoldHooks
    + ListLegalHoldsHooks
{
}

impl<
        T: ExportSubjectDataHooks
            + RestrictSubjectHooks
            + EraseSubjectHooks
            + PlaceLegalHoldHooks
            + ListErasureReceiptsHooks
            + FetchSubjectExportHooks
            + LiftSubjectRestrictionHooks
            + ReleaseLegalHoldHooks
            + ListLegalHoldsHooks,
    > SubjectRightsServiceHooks for T
{
}

/// Adds the route of every contract component `subject-rights-service` implements to `routes`, each answered by `service` after the checks the specification states for it.
pub fn subject_rights_service_routes<A, S, H>(
    routes: strata_runtime::Routes<A>,
    service: std::sync::Arc<S>,
    hooks: std::sync::Arc<H>,
) -> strata_runtime::Routes<A>
where
    A: strata_runtime::Authorizer,
    S: crate::contracts::SubjectRightsService + Send + Sync + 'static,
    H: SubjectRightsServiceHooks,
{
    let routes = serve_export_subject_data(routes, service.clone(), hooks.clone());
    let routes = serve_restrict_subject(routes, service.clone(), hooks.clone());
    let routes = serve_erase_subject(routes, service.clone(), hooks.clone());
    let routes = serve_place_legal_hold(routes, service.clone(), hooks.clone());
    let routes = serve_list_erasure_receipts(routes, service.clone(), hooks.clone());
    let routes = serve_fetch_subject_export(routes, service.clone(), hooks.clone());
    let routes = serve_lift_subject_restriction(routes, service.clone(), hooks.clone());
    let routes = serve_release_legal_hold(routes, service.clone(), hooks.clone());
    serve_list_legal_holds(routes, service, hooks)
}

